import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"EvalVerse: Pipeline-Aware and Expert-Calibrated Benchmarking for Professional Cinematic Video Generation","description":"","frontmatter":{"title":"EvalVerse: Pipeline-Aware and Expert-Calibrated Benchmarking for Professional Cinematic Video Generation","arxiv":"2605.23271","date":"2026-05-22","authors":"Songlin Yang, Haobin Zhong, Ruilin Zhang, Xiaotong Zhao, Shuai Li, Kai Zheng, Xuyi Yang, Zhe Wang, Zhenchen Tang, Yang Li, Bohai Gu, Zhengwei Peng, Yidan Huang, Mengzhou Luo, Yihang Bo, Dalu Feng, Yujia Zhang, Juntao Ma, Ruiqi Wang, Lvmin Zhang, Yuwei Guo, Frank Guan, Maneesh Agrawala, Hongbo Fu, Alan Zhao, Anyi Rao","categories":"cs.CV, cs.AI","topics":"影视级视频评测, 专家校准, 奖励信号基础设施","outline":[2,2]},"headers":[],"relativePath":"papers/2605.23271.md","filePath":"papers/2605.23271.md","lastUpdated":null}'),l={name:"papers/2605.23271.md"};function e(i,s,m,r,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="evalverse-pipeline-aware-and-expert-calibrated-benchmarking-for-professional-cinematic-video-generation" tabindex="-1">EvalVerse: Pipeline-Aware and Expert-Calibrated Benchmarking for Professional Cinematic Video Generation <a class="header-anchor" href="#evalverse-pipeline-aware-and-expert-calibrated-benchmarking-for-professional-cinematic-video-generation" aria-label="Permalink to &quot;EvalVerse: Pipeline-Aware and Expert-Calibrated Benchmarking for Professional Cinematic Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.23271" target="_blank" rel="noreferrer">2605.23271</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-22</td></tr><tr><td><strong>作者</strong></td><td>Songlin Yang, Haobin Zhong, Ruilin Zhang, Xiaotong Zhao, Shuai Li, Kai Zheng, Xuyi Yang, Zhe Wang, Zhenchen Tang, Yang Li, Bohai Gu, Zhengwei Peng, Yidan Huang, Mengzhou Luo, Yihang Bo, Dalu Feng, Yujia Zhang, Juntao Ma, Ruiqi Wang, Lvmin Zhang, Yuwei Guo, Frank Guan, Maneesh Agrawala, Hongbo Fu, Alan Zhao, Anyi Rao</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把影视工业的前期/拍摄/后期流程当诊断透镜，拆成 7 大方面 45 个子维度 196 条评判理由，再用专用感知算子做证据先验 + 两阶段专家校准微调 VLM，把&quot;好不好看&quot;变成可计算、可解释、可当 reward 的分数。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型正在从&quot;能生成&quot;迈向&quot;影视级&quot;，而高质量影视数据稀缺让 SFT 撞上了扩展瓶颈，社区因此转向 RL（RLHF、GRPO）和 agentic workflow。这个转向有一个前提条件：得有可信的、细粒度的评价信号。评测因此从被动的排行榜变成了整条链路的瓶颈。</p><p>论文把当前的缺口切成两块，都很具体。<strong>目标缺口</strong>：&quot;对不对&quot; vs &quot;好不好&quot;。现有基准（EvalCrafter、VBench 系列、UniVBench）主要衡量 prompt-following 和视觉元素是否出现，完全不评表演、摄影、审美这些专业制作要求的东西。<strong>方法与可信度缺口</strong>：评&quot;好不好&quot;要求领域专家知识和主观细微判断，通用 VLM 给不了这种专业严谨性，而人类专家评估虽是金标准却贵到不可扩展。作者把这称为&quot;评测悖论&quot;。</p><p>价值落点很明确：EvalVerse 的目标不是再造一张排行榜，而是给 RL 提供密集的、专家对齐的 reward 向量，给 agentic workflow 提供可解释的诊断反馈。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>通用基准这条线：FVD 和 CLIP-Score 这类整体指标抓不住时序动态和语义精度；VBench 首次把视频质量分解成多层维度；VBench 2.0 转向内在忠实度（复杂场景下文本与内容的错位）；VBench++ 扩展了任务覆盖；UniVBench 尝试统一评测视频基础模型。这条线的共同问题是停留在&quot;对不对&quot;。</p><p>专业化这条线更接近本文。Stable Cinemetrics 提出了面向专业视频的结构化 taxonomy，聚焦相机控制与灯光的精度；CineTechBench 收窄到评测模型对特定摄影技法的理解与生成；VADB 建了带专业多维标注的大规模视频美学数据库。论文的 Table 1 和 Table 2 用两张对照表精确指出这些工作缺什么：<strong>没有一个覆盖 audio-sync 和 multi-shot</strong>，且大多是无声、单镜头，测试 prompt 靠人为排列组合孤立的电影元素得到，既反映不了真实的影视分布，也不提供参考视频。EvalVerse 是表里唯一在 T2V / R2V / 带声视频 / 多镜头四项模态覆盖上全勾、同时具备 pipeline-aware 和 expert-guided 的框架。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个观察出发：影视行业评价一部作品从来不是打一个总分，而是分工种审查 —— 美术、摄影、表演、剪辑、声音各有专业标准。这套标准已经被行业验证了上百年，且天然是<strong>结构化</strong>的。</p><p>再从一个失败模式出发：把视频丢给通用 VLM 问&quot;这个视频好不好&quot;，得到的分数与专业人士的判断脱节。原因不难推断 —— &quot;好&quot;这个词在没有专业语境时是空的，VLM 只能回退到&quot;清晰、明亮、构图居中&quot;这类朴素审美。</p><p>两条合起来，做法就浮现了：不要问&quot;好不好&quot;，而要<strong>按行业工种逐项审查</strong>。这里有一个不显然的设计决策 —— 现代基础模型是端到端生成的，并不真的存在&quot;前期/拍摄/后期&quot;三个步骤。作者的处理是把制作流程当成<strong>诊断透镜</strong>而非生成假设：对最终视频做反向工程，把它的多模态元素映射回三个概念阶段。这样既拿到了行业标准的结构性，又不对生成过程做错误假设。</p><p>最后一个障碍是 VLM 的能力边界。抽象维度（比如&quot;节奏层次&quot;）无论怎么写 prompt 都无法分解成零样本可观测的 token。作者的应对是承认这个天花板，然后分三层去够：prompt 层换掉超出模型能力的维度，融合层用 MLP 学权重，参数层直接微调注入知识。这个&quot;先测能力边界再设计指标&quot;的顺序，比先定义理想指标再硬套要务实得多。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>&quot;好不好看&quot;之所以测不了，是因为它被当成一个整体的主观判断。影视工业早已把它拆成了工种化的、有明确判据的检查项。把这套拆解搬过来当诊断透镜，再用专用感知算子给 VLM 补上它天生弱的低层证据（身份追踪、唇音同步），最后用专家标注微调把语言层面表达不出的抽象判断直接写进参数 —— 主观性就从&quot;不可计算&quot;变成了&quot;分层可计算&quot;。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以评估一段带对白的双镜头生成片段为例。</p><p><strong>Taxonomy</strong>。3 个制作阶段 → 7 个电影方面 → 18 个主维度 → 45 个子维度 → 196 条细粒度评判理由。前期（Pre-Production）只有 Visual Concept Design，审角色可辨识性、服装合理性、环境合理性、类型风格纯度。拍摄（Production）包含 Acting（一致性/动作/表情）、Cinematography（构图/镜头光学/运镜节奏）、Aesthetics（渲染质量/物理/时序一致性、色彩、材质、光照）、Affectivity（情绪基调建立与情绪弧线）。后期（Post-Production）包含 Multi-Shot（场景一致性、叙事连续性、空间连续性含 180 度轴线规则；镜头时长合理性、节奏层次）和 Sound Design（人声音质、唇音同步、叙事音效；环境音保真度、配乐对齐）。</p><p><strong>数据引擎（Real-to-Gen）</strong>。从百万级专业影视数据库出发，用多模态感知套件抽结构化元数据（相机参数、角色属性、环境），经工业级处理和人工核验成为 ground-truth 元数据；按九个核心电影维度做<strong>按比例采样</strong>而非随机采样；再用 Gemini 3.1 Pro 把结构化元数据和原始 caption 合成带专业术语的测试 prompt，参考类任务用 Nano Banana Pro 从关键帧生成高保真参考图，深度参考用 ControlNet 生成深度序列。这样得到的测试对带<strong>真实参考视频</strong>，避免了纯 prompt 基准固有的随机偏差。</p><p><strong>机器评测的两步走</strong>。第一步用一组专用算子提取确定性证据 —— DINO 和 InsightFace 做跨帧身份追踪，YOLO 做语义锚定，SyncNet 做视听同步，Whisper 做语音情绪识别。第二步把这份证据先验连同 prompt、参考、专家设计的多问题一起交给微调过的 VLM，让它先出 CoT 再打分，CoT 里嵌了 <strong>Self-Reflection</strong>（强制回头检查自己是否幻觉）和 <strong>Context-Aware Gating</strong>（叙事语境不需要某个指标时直接跳过，比如一场平静的戏不该被&quot;表情张力不足&quot;扣分）。</p><p><strong>人机校准三层</strong>。Prompt 层：迭代替换掉过于抽象、超出模型感知与推理能力的维度和多问题。Fusion 层：用一个轻量 MLP 在人工标注上学各个多问题、算子证据、VLM 感知结果在 CoT 内的分数配比，缓解算子的域外失效和 VLM 的推理错误。Parameter 层：在专家数据集上微调，把电影领域知识写进参数。</p><p><strong>人工评测协议</strong>是三段式：标注员对 prompt、GT 视频、模型输出做 side-by-side 并在所有预定义维度上给出强制的判别性排序；资深影视从业者逐条复核给 Pass/Fail；专家做最终审计消除系统性偏差。全流程涉及 34 位专业专家。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>证据先验</strong>是一组算子输出的并集：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">prof</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.1304em;vertical-align:-1.3021em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">⋃</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ϕ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mclose">)</span></span></span></span></span></p><p>写成并集而非某种融合，说明这些算子输出的是<strong>互不重叠的确定性事实</strong>（谁的脸在哪一帧、唇形和音素对不对），而不是需要加权平均的分数。这一步的意义是把 VLM 不擅长的细粒度时序追踪和低层感知外包出去，只留下它擅长的语义推理。</p><p><strong>最终打分</strong>带一个门控：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6183em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathbb">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gate</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mclose">)</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord mathnormal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">prof</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal">Q</span><span class="mclose">)</span></span></span></span> 是完整多模态上下文，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal">Q</span></span></span></span> 是该维度的专家设计问题集。乘性门控 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.975em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathbb">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gate</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">}</span></span></span></span> 的作用是让不适用的指标<strong>归零而非低分</strong>。这个区分很关键：一段刻意平静的空镜如果被&quot;情绪强度不足&quot;扣分，评测本身就在惩罚正确的艺术选择。</p><p><strong>微调分两阶段</strong>。第一阶段在成对比较数据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)}</span></span></span></span> 上最小化 Bradley-Terry 排序损失：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2031em;vertical-align:-0.3531em;"></span><span class="mord">−</span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2901em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3531em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord"><span class="delimsizing size1">]</span></span></span></span></span></span></p><p>这一步学的是<strong>相对</strong>审美偏好。Bradley-Terry 的性质决定了它只约束分差、不约束绝对尺度，所以单靠这一步拿不到可解释的绝对分。</p><p>第二阶段在点式数据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">score</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)}</span></span></span></span> 上做交叉熵微调，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是专家写的 CoT，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是绝对分：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7387em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.6021em;vertical-align:-0.7521em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.3479em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7521em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">score</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">CE</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord"><span class="delimsizing size1">]</span></span></span></span></span></span></p><p>模型被训练成<strong>先自回归生成理由再输出分数</strong>。把两阶段拆开的理由可以推断出来：偏好数据便宜量大但只给序，专家 CoT 数据贵但给出绝对锚点和推理过程，先用前者建立排序能力再用后者做尺度校准，是成本最优的顺序。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：现有模型在专业维度上的真实排布是什么？</strong> 评了 11 个模型，覆盖闭源（Kling-v3-Omni、Seedance 2.0、Happy Horse 1.0、Vidu-Q2-Pro、Hailuo 2.3）、开源（Hunyuan 1.5 8.3B、LTX2 19B、Wan2.2 14B）和专攻多镜头/视听的（HoloCine 14B、MultiShotMaster 14B、UniVideo）。结论是层次分明：Seedance 2.0 综合最强且各维度都稳；Kling-v3-Omni 和 Happy Horse 1.0 构成第二梯队，前者强在审美、摄影、视觉概念和声音，后者强在摄影、视觉概念设计、表演和多镜头组织；Hailuo 2.3 与 Vidu-Q2-Pro 是中间层，弱在情绪和声音维度；HoloCine、UniVideo、MultiShotMaster 的能力剖面明显不均衡 —— HoloCine 在场景合理性和多镜头一致性上有局部优势但表演与渲染拖后腿，MultiShotMaster 只在镜头时长合理性上占优。这种&quot;专精模型在自己的强项之外全面塌陷&quot;的画像，正是单一总分基准看不见的东西。</p><p><strong>问题二：机器打分能不能替代专家？</strong> 用三个互补角度验证。第一，逐维度的 pairwise win-ratio 对照表，机器预测与专家标注的绝对值贴近。第二，每个维度的 SRCC 和 PLCC 及其 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 值 —— 以 Visual Concept Design 的 Character 一项为例，SRCC <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">0.7529</span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0075</span></span></span></span>）、PLCC <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">0.7664</span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0059</span></span></span></span>），基于 11 个模型。第三，散点图加线性拟合的趋势一致性可视化。</p><p><strong>问题三：三层校准里哪一层最关键？</strong> 统计结果给出了一个和设计直觉吻合的模式：像素可 grounding 的维度（视觉概念设计、摄影、表演、审美、情绪）主要靠 prompt 层 CoT 就能取得强对齐，说明 CoT 数字化已经能覆盖大多数电影判据；而抽象且时序纠缠的维度需要额外的任务专属 SFT，这些维度反而取得了<strong>最高</strong>的专家一致性。作者据此论证：参数层知识注入是最难维度上的决定性一步，纯自然语言 rationale 关不上这个缺口。他们的解释很直接 —— 像&quot;节奏层次&quot;这样的概念无论 prompt 写得多细都无法被稳健分解成零样本可观测的 token。</p><p>局限方面作者列了三条：VLM 处理离散关键帧而非连续流，时序感知受限；扩展到十分钟以上的宏观叙事需要更强的长上下文推理；前卫艺术风格的评估仍然困难。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频生成正在转向 RL 和 agentic workflow，而这两者都要求可信的细粒度 reward，评测因此成了瓶颈。现有基准只测&quot;对不对&quot;，测&quot;好不好&quot;需要专业知识，而人工评估不可扩展、通用 VLM 不够专业。EvalVerse 把影视制作流程当诊断透镜，拆成 3 阶段 7 方面 18 主维度 45 子维度 196 条评判理由，并用真实影视库按比例采样构造带参考视频的测试对。机器侧先用 DINO/InsightFace/SyncNet/Whisper 等算子提取确定性证据先验，再让专家校准过的 VLM 出 CoT 打分，配 Self-Reflection 和 Context-Aware Gating。三层校准的实证结论是：像素可 grounding 的维度靠 CoT 就够，抽象时序维度必须靠参数层 SFT。</p><p><strong>3 句话版</strong>：把行业工种化的评审标准搬过来，&quot;主观审美&quot;就变成了分层可计算的检查项。VLM 天生弱的低层感知外包给专用算子，天生表达不出的抽象判断直接微调进参数。产物不是排行榜，而是能给 RL 当 reward、给 agent 当评审的诊断基础设施。</p><p><strong>1 句话版</strong>：先量清楚 VLM 的能力边界，再决定哪些维度用 prompt、哪些必须用参数注入。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>196 条专家评判理由构成的分数向量，其加权聚合能代表&quot;好&quot;</strong>。整个框架把电影质量分解成正交的子维度分别打分，隐含假设是各维度的贡献可分离、可聚合。但影视创作里最有价值的判断恰恰来自<strong>维度间的违反</strong>：手持晃动在正规摄影标准下是&quot;运镜不合理&quot;，在纪实风格里是刻意的语言；过曝在技术审查里扣分，在特定情绪段落里是修辞。</p><p>论文确实意识到了这个风险并给了部分对策 —— Context-Aware Gating 允许在叙事语境不支持时跳过指标。但门控是二值的（做/不做），它能处理&quot;这里不该评表情&quot;，处理不了&quot;这里的技术缺陷正是艺术选择&quot;。作者自己在局限里承认&quot;评估无边界的前卫风格仍然困难&quot;，这正是同一个问题的症状。</p><p>更实际的风险在下游。论文的核心卖点是给 RL 提供 reward 向量。一个由正交检查项加权而成的 reward，被 policy 优化到极致时会收敛到&quot;每一项都不扣分&quot;的作品 —— 也就是技术上无可指摘、艺术上平庸的中位数影像。这是 reward hacking 的经典形态，而论文没有提供任何针对该风险的证据（既没有用 EvalVerse 做 RL 的实验，也没有分析高分样本是否出现风格坍缩）。可以推断这是该框架最需要被验证的地方。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现整套 taxonomy 和标注流程，一周内可做：</p><ul><li>数据：取 60 段真实电影片段，人为分成两组 —— 30 段&quot;技法规范&quot;（构图稳、曝光准、运镜平滑）和 30 段公认优秀但<strong>刻意违反技法</strong>的名场面（手持长镜、极端过曝、跳切）。再取 30 段生成模型输出的平庸但技术无瑕的片段。</li><li>实现：不训练。用一个通用 VLM，按 EvalVerse 公开的维度定义写 prompt，对三组视频逐维度打分并加权成总分。</li><li>测量：三组的总分分布；重点看&quot;违反技法的名场面&quot;与&quot;技术无瑕的生成片段&quot;谁分高。</li><li>判据：若技术无瑕的平庸生成片段总分高于违反技法的名场面，则支持&quot;正交分解会奖励中位数影像&quot;的担忧，用它当 RL reward 有风格坍缩风险；若名场面仍然得分更高，说明 gating 与维度设计确实容纳了艺术性违规，反驳该担忧。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击针对 §7 人机对齐结果的<strong>替代解释</strong>。EvalVerse 报告的是逐维度 win-ratio 相关性，基于 <strong>11 个模型</strong>的排序。但当代生成模型在整体质量上高度相关 —— 一个在渲染质量上强的模型，通常在光照、材质、时序一致性上也强。这意味着一个只测<strong>单一整体质量</strong>的朴素评估器，也能在几乎所有维度上复现出高相关性，因为被排序的对象本身就沿着一根主轴分布。</p><p>具体实验：构造一个&quot;单维度 baseline&quot; —— 只让通用 VLM 给出一个整体好坏分，然后把这个分复制到全部 45 个子维度上，用同样的协议算 SRCC/PLCC。如果这个 baseline 也拿到接近的相关系数，那么高对齐就不构成&quot;细粒度诊断有效&quot;的证据，论文的核心方法论主张需要重新论证。真正能区分二者的是<strong>在整体质量相近的模型对上</strong>的判别力，而这恰恰需要更多模型、或者针对性构造的对照样本（同一模型在不同维度上被人为削弱的变体），论文都没有做。</p><p>另一类可预测失败：算子证据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">prof</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是用 DINO、InsightFace、YOLO、SyncNet 这些在<strong>真实视频</strong>上训练的模型提取的。生成视频存在特有的分布外伪影（时序闪烁、结构崩塌、非自然的面部形变），这些算子在其上的可靠性未被评估。作者在 Fusion 层用 MLP 学权重来&quot;缓解算子域外失效&quot;，说明他们知道这个问题存在，但缓解不等于量化 —— 论文没有给出算子在生成视频上的准确率数字，这是证据链上的空白。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：EvalVerse 把评测建模成对成品的<strong>静态审计</strong>。它能告诉你&quot;多镜头节奏层次得 2 分&quot;，但给不出&quot;该怎么改&quot;。对 agentic workflow 而言这远远不够 —— agent 需要的是可执行的修改指令，不是诊断分数。</p><p><strong>新 framing</strong>：把评测器重构成<strong>反事实编辑提议器</strong>。不再问&quot;这段视频有多好&quot;，而是问&quot;最小改动什么，分数会跳升最多&quot;。评测的输出从标量向量变成一组带预期增益的编辑操作（把第二个镜头缩短 0.4 秒、把主体位置右移出中心、降低第三镜的色温）。这不是在评测器后面接一个改写模块，而是换了建模对象 —— 从质量函数换成质量函数的<strong>梯度</strong>，目标从&quot;逼近专家分数&quot;变成&quot;逼近专家会给出的修改意见&quot;。影视行业本来就是这样工作的：导演给的是修改笔记，不是分数。</p><p><strong>可借鉴的相邻工具</strong>：可解释 AI 里的反事实解释生成（找到使预测翻转的最小输入扰动）提供了现成的形式化；视频编辑模型（同期的 Bernini 那类）提供了执行编辑的能力；两者结合可以让&quot;提议—执行—重评&quot;闭环跑起来。专家标注侧也不必重来，影视工业的<strong>修改笔记</strong>本身就是天然的监督数据。</p><p><strong>第一个实验</strong>：从 EvalVerse 的低分样本里取一批，请专家写下&quot;改哪一处能救回来&quot;的最小修改笔记（每条一句话，可执行）。训练一个模型从视频 + 诊断分预测这条笔记，再用视频编辑模型执行，最后用 EvalVerse 重新打分。判据是：预测笔记执行后的分数提升，能否接近专家笔记执行后的提升。若能接近，说明评测器内部确实编码了可操作的改进方向，静态审计可以升级成闭环导演助手；若差距很大，则说明当前的分数只捕捉了&quot;哪里不好&quot;而非&quot;为什么不好&quot;，taxonomy 需要在归因粒度上再往下切一层。</p>',62)])])}const u=a(l,[["render",e]]);export{h as __pageData,u as default};
